25	// Built-in functional engine ids (the qemu64/qemu32 pair). Declared once here so
26	// builtin_qemu_arch, the hybrid plan steps, and `run --mode fast` acceptance all
27	// agree -- a renamed literal would otherwise break find_engine() lookups only at
28	// run time.
29	inline constexpr const char* kQemuId64 = "qemu64";
30	inline constexpr const char* kQemuId32 = "qemu32";
31	
32	struct Discovery {
33	  std::vector<EngineDescriptor> engines;   // deduped by id; qemu first
34	  std::vector<std::string> warnings;       // binaries that failed to describe
35	};
