69	// Select the cycle-accurate engine for `run --mode cycle` from an
70	// already-discovered set (pure; spawns nothing). With `want_id` empty, default
71	// to the sole cycle-accurate engine -- erroring if there are none or more than
72	// one (ambiguous). With `want_id` set, that engine must exist and be
73	// cycle-accurate. Returns nullptr and sets `err` (naming the available
74	// cycle-accurate ids) on any failure; the returned pointer aliases into
75	// `engines`, so it must outlive the result.
76	inline const EngineDescriptor* resolve_accurate_engine(
77	    const std::vector<EngineDescriptor>& engines, const std::string& want_id,
78	    std::string& err) {
79	  auto is_accurate = [](const EngineDescriptor& e) {
80	    return e.kind == "cycle-accurate";
81	  };
82	  auto accurate_ids = [&] {
83	    std::vector<std::string> ids;
84	    for (const EngineDescriptor& e : engines)
85	      if (is_accurate(e)) ids.push_back(e.id);
86	    return join(ids, ", ");
87	  };
88	
89	  if (!want_id.empty()) {  // explicit --engine
90	    for (const EngineDescriptor& e : engines) {
91	      if (e.id != want_id) continue;
92	      if (is_accurate(e)) return &e;
93	      err = "engine '" + want_id + "' is " +
94	            (e.kind.empty() ? "not cycle-accurate" : e.kind) +
95	            "; a cycle-accurate engine is required";
96	      return nullptr;
97	    }
98	    std::string have = accurate_ids();
99	    err = "no engine '" + want_id + "'" +
100	          (have.empty() ? " (no cycle-accurate engines found)"
101	                        : " (cycle-accurate engines: " + have + ")");
102	    return nullptr;
103	  }
104	
105	  // No --engine: default to the sole cycle-accurate engine.
106	  const EngineDescriptor* sole = nullptr;
107	  int n = 0;
108	  for (const EngineDescriptor& e : engines)
109	    if (is_accurate(e)) { sole = &e; ++n; }
110	  if (n == 1) return sole;
111	  if (n == 0)
112	    err = "model cycle: no cycle-accurate engine found "
113	          "(build one with: scripts/build_all.sh vsim)";
114	  else
115	    err = "model cycle: multiple cycle-accurate engines; select one with "
116	          "--engine (have: " + accurate_ids() + ")";
117	  return nullptr;
118	}
119	
120	}  // namespace andes_sim
121	
122	#endif  // ANDESIM_ENGINE_REGISTRY_HPP
