18	int main() {
19	  using namespace andes_sim;
20	
21	  // --- vsim_scan_dir honors $VSIM_BIN_DIR (external, like $QEMU_BIN_DIR) ---
22	  setenv("VSIM_BIN_DIR", "/opt/vsim_andesim/build", /*overwrite=*/1);
23	  CHECK(vsim_scan_dir() == fs::path("/opt/vsim_andesim/build"));
24	  unsetenv("VSIM_BIN_DIR");
25	
26	  // --- config_env_value: env first, else the KEY= line in the config file ---
27	  fs::path cfg = fs::temp_directory_path() /
28	                 ("andesim_cfgenv_test_" + std::to_string(::getpid()) + ".env");
29	  {
30	    std::ofstream f(cfg);
31	    f << "# per-host config\n"
32	         "HYBRID_TOOLCHAIN=/opt/tc\n"
33	         "  VSIM_BIN_DIR=/from/config/build\n";  // leading ws tolerated
34	  }
35	
36	  // env unset -> value comes from the config file
37	  unsetenv("VSIM_BIN_DIR");
38	  CHECK(config_env_value("VSIM_BIN_DIR", cfg) == "/from/config/build");
39	
40	  // env set (non-empty) wins over the config file
41	  setenv("VSIM_BIN_DIR", "/from/env/build", /*overwrite=*/1);
42	  CHECK(config_env_value("VSIM_BIN_DIR", cfg) == "/from/env/build");
43	  unsetenv("VSIM_BIN_DIR");
44	
45	  // a key absent from both env and file -> empty
46	  CHECK(config_env_value("NO_SUCH_KEY", cfg).empty());
47	
48	  // a missing config file is not an error -> empty (env still consulted first)
49	  CHECK(config_env_value("VSIM_BIN_DIR", "/no/such/file.env").empty());
50	
51	  // builtin_qemu resolves its binary the same way: $VSIM_QEMU (the explicit
52	  // binary) wins over the QEMU_BIN_DIR / default fallback.
53	  setenv("VSIM_QEMU", "/opt/qemu/qemu-system-riscv64", /*overwrite=*/1);
54	  CHECK(builtin_qemu().bin_path == "/opt/qemu/qemu-system-riscv64");
55	  unsetenv("VSIM_QEMU");
56	
57	  // rv64 "qemu64" vs rv32 "qemu32": id, xlen, and binary differ.
58	  const EngineDescriptor q64 = builtin_qemu_arch(64);
59	  const EngineDescriptor q32 = builtin_qemu_arch(32);
60	  CHECK(q64.id == "qemu64");
61	  CHECK(q64.xlen == 64);
62	  CHECK(q32.id == "qemu32");
63	  CHECK(q32.xlen == 32);
64	  CHECK(q64.bin_path.ends_with("qemu-system-riscv64"));
65	  CHECK(q32.bin_path.ends_with("qemu-system-riscv32"));
66	  // model=fast pins a concrete andes core (andes_ae350's generic default -cpu
67	  // hangs the vplat fixtures): the vector-capable ax46mpv (rv64) / a46mpv (rv32).
68	  // andesim passes NO vlen -- the cpu model's own QEMU default applies; a user
69	  // who wants a specific width passes it via the post-`--` -cpu, which still wins.
70	  auto fast_cpu = [](const EngineDescriptor& e) -> std::string {
71	    const std::vector<std::string>* st = e.invoke_for("standalone");
72	    if (!st) return "";
73	    for (std::size_t i = 0; i + 1 < st->size(); ++i)
74	      if ((*st)[i] == "-cpu") return (*st)[i + 1];
75	    return "";
76	  };
77	  CHECK(fast_cpu(q64) == "andes-ax46mpv");
78	  CHECK(fast_cpu(q32) == "andes-a46mpv");
79	  // rv64 keeps the hybrid fast-leg; rv32 hybrid is not wired yet.
80	  CHECK(q64.invoke_for("fast-leg") != nullptr);
81	  CHECK(q32.invoke_for("fast-leg") == nullptr);
82	
83	  // resolve_accurate_engine serves BOTH --mode cycle and --mode hybrid, so its
84	  // rejection of a functional engine must be mode-agnostic (the caller already
85	  // prefixes "andesim run --mode <mode>:"); it must not hardcode "model cycle".
86	  {
87	    const std::vector<EngineDescriptor> engs = {q64};  // qemu64 is functional
88	    std::string err;
89	    CHECK(resolve_accurate_engine(engs, "qemu64", err) == nullptr);
90	    CHECK(err.find("functional") != std::string::npos);
91	    CHECK(err.find("cycle-accurate") != std::string::npos);
92	    CHECK(err.find("model cycle") == std::string::npos);
93	  }
94	
95	  // normalize_engine_label speaks the CLI's vocabulary: an engine that reports
96	  // its marker delimiter under the internal name "csr" (via --describe) is shown
97	  // as "marker" (what `--trigger marker` expects), like verilator -> vsim.
98	  {
99	    EngineDescriptor d;
100	    d.type = "verilator";
101	    d.id = "verilator:cfg";
102	    d.triggers = {"csr", "pc"};
103	    normalize_engine_label(d);
104	    CHECK(d.type == "vsim");
105	    CHECK(d.id == "vsim:cfg");
106	    CHECK((d.triggers == std::vector<std::string>{"marker", "pc"}));
107	  }
108	
109	  std::remove(cfg.c_str());
110	  return andes_sim::test::report("engine-registry");
111	}
