52	std::vector<Row> doctor_artifacts() {
53	  const fs::path root = repo_root();
54	  struct A {
55	    const char* label;
56	    const char* env;
57	    fs::path def;
58	  };
59	  // The vsim/qemu defaults come straight from the registry's resolvers
60	  // (vsim_scan_dir / builtin_qemu_arch), so doctor reports the same paths the
61	  // engine would use instead of re-deriving the env -> QEMU_BIN_DIR -> legacy
62	  // tiers. Env overrides still match hsim's _ARTIFACT_ENV; order (vsim, qemu,
63	  // plugin) mirrors the golden's dict order.
64	  const A arts[] = {
65	      {"vsim", "VSIM_BIN", vsim_scan_dir() / "sim_ax45mpv_premium"},
66	      {"qemu64", "VSIM_QEMU", builtin_qemu_arch(64).bin_path},
67	      {"plugin", "VSIM_PLUGIN", default_plugin_path()},
68	  };
69	  std::vector<Row> rows;
